(3043713, 427445, 64209, '<td valign="top">I think this would have worked well if the mask had not blown out - is it metal? paper?</td>', 'I think this would have worked well if the mask had not blown out - is it metal? paper?', '2006-11-19 12:43:04.000000', NULL, 1),
(3043715, 426884, 64209, '<td valign="top">Nice shot, I like the feeling of movement in the hair.</td>', 'Nice shot, I like the feeling of movement in the hair.', '2006-11-19 12:43:59.000000', NULL, 1),
(3043717, 427155, 64209, '<td valign="top">Great lighting</td>', 'Great lighting', '2006-11-19 12:44:28.000000', NULL, 1),
