(3043720, 426191, 64209, '<td valign="top">The hat does not have enough definition/light but other than that, cool shot!</td>', 'The hat does not have enough definition/light but other than that, cool shot!', '2006-11-19 12:47:56.000000', NULL, 1),
(3043726, 425785, 64209, '<td valign="top">Serious headgear - maybe if you had cropped a little more on the right, you could have given the impression the hat went on and on and on . . .or maybe not cropped so tight.  Dunno,</td>', 'Serious headgear - maybe if you had cropped a little more on the right, you could have given the impression the hat went on and on and on . . .or maybe not cropped so tight.  Dunno,', '2006-11-19 12:54:15.000000', NULL, 1),
(3043768, 427378, 66515, '<td valign="top">Too washed out- it is difficult to see the hat as the focus is on the background wall. I''m not sure I would have chose B&amp;W for this photo.</td>', 'Too washed out- it is difficult to see the hat as the focus is on the background wall. I''m not sure I would have chose B&W for this photo.', '2006-11-19 13:26:15.000000', NULL, 1),
(3043773, 426862, 66515, '<td valign="top">The focus of the photo is more on the plane (especially the bright logo) than the pilot (and his head wear).</td>', 'The focus of the photo is more on the plane (especially the bright logo) than the pilot (and his head wear).', '2006-11-19 13:27:54.000000', NULL, 1),
(3043777, 427391, 66515, '<td valign="top">Very difficult to make out the hat in this photo. I''m more interested in the background setting.</td>', 'Very difficult to make out the hat in this photo. I''m more interested in the background setting.', '2006-11-19 13:29:51.000000', NULL, 1),
(3043781, 427008, 66515, '<td valign="top">The white sheet background is very dull and actually distracting.</td>', 'The white sheet background is very dull and actually distracting.', '2006-11-19 13:30:51.000000', NULL, 1),
(3043784, 427534, 66515, '<td valign="top">The brim is a bit washed out.</td>', 'The brim is a bit washed out.', '2006-11-19 13:31:45.000000', NULL, 1),
(3043789, 425881, 66515, '<td valign="top">Interesting character!</td>', 'Interesting character!', '2006-11-19 13:33:36.000000', NULL, 1),
(3043794, 425162, 66515, '<td valign="top">A bit oversaturated and the texture of the hat looks odd. I like that the focus is on the hat though (especially with the eyes looking up! Very cool idea!).</td>', 'A bit oversaturated and the texture of the hat looks odd. I like that the focus is on the hat though (especially with the eyes looking up! Very cool idea!).', '2006-11-19 13:35:03.000000', NULL, 1),
(3043795, 427454, 67258, '<td valign="top">The headwaear, in the form of the helmet is just too incidental to this to truly meet the challenge in my opinion.  The idea is sound, but I feel you could have done much more with the composition.</td>', 'The headwaear, in the form of the helmet is just too incidental to this to truly meet the challenge in my opinion.  The idea is sound, but I feel you could have done much more with the composition.', '2006-11-19 13:35:14.000000', NULL, 1),
(3043796, 427391, 67258, '<td valign="top">I have left this one til last to vote on, as I just haven''t been able to work out what it is I am looking at.  The subject is presumably the white thing on top of the rock, but I am still unable to make it out....</td>', 'I have left this one til last to vote on, as I just haven''t been able to work out what it is I am looking at.  The subject is presumably the white thing on top of the rock, but I am still unable to make it out....', '2006-11-19 13:35:28.000000', NULL, 1),
