(3043807, 425785, 66515, '<td valign="top">Too bad the back of his headwear is cut off. Otherwise, I really like the profile.</td>', 'Too bad the back of his headwear is cut off. Otherwise, I really like the profile.', '2006-11-19 13:38:48.000000', NULL, 1),
(3043809, 427562, 66515, '<td valign="top">Too dark to really see the hat.</td>', 'Too dark to really see the hat.', '2006-11-19 13:39:44.000000', NULL, 1),
