(3043814, 426347, 66515, '<td valign="top">A bit overexposed (i.e. arm) which draws the focus away from his face &amp; headscarf (I apologize, I don''t know the proper term for his "headwear").</td>', 'A bit overexposed (i.e. arm) which draws the focus away from his face & headscarf (I apologize, I don''t know the proper term for his "headwear").', '2006-11-19 13:42:53.000000', NULL, 1),
(3043816, 426857, 66515, '<td valign="top">Subject isn''t focused well and reflection on helmet is distracting.</td>', 'Subject isn''t focused well and reflection on helmet is distracting.', '2006-11-19 13:44:20.000000', NULL, 1),
(3043821, 425583, 66515, '<td valign="top">My boyfriend and I are at odds with this one- but I win...she''s not embarrassed...she''s adorable in her Christmas bonnet (I assume "Lilly" is a she)!</td>', 'My boyfriend and I are at odds with this one- but I win...she''s not embarrassed...she''s adorable in her Christmas bonnet (I assume "Lilly" is a she)!', '2006-11-19 13:46:54.000000', NULL, 1),
