(3043828, 427611, 66515, '<td valign="top">Fun picture. Would have preferred a sharper image on the left (less glow). But it did make us laugh!</td>', 'Fun picture. Would have preferred a sharper image on the left (less glow). But it did make us laugh!', '2006-11-19 13:49:42.000000', NULL, 1),
(3043829, 427166, 66515, '<td valign="top">Simple yet effective!</td>', 'Simple yet effective!', '2006-11-19 13:50:40.000000', NULL, 1),
