(3044051, 427335, 56109, '<td valign="top">excellent use of colors. love this picture.</td>', 'excellent use of colors. love this picture.', '2006-11-19 16:21:20.000000', NULL, 1),
(3044057, 427356, 35602, '<td valign="top">Love the classic net hat.  Wish it were a little lighter.</td>', 'Love the classic net hat.  Wish it were a little lighter.', '2006-11-19 16:24:55.000000', NULL, 1),
(3044059, 427566, 35602, '<td valign="top">You can play golf on Christmas?  Must be from Texas.  Nice contrast.</td>', 'You can play golf on Christmas?  Must be from Texas.  Nice contrast.', '2006-11-19 16:25:43.000000', NULL, 1),
(3044065, 427156, 35602, '<td valign="top">Lighting is a bit dark, though you tried using it creatively.  A reflecting board on the right would have lit up that side better.</td>', 'Lighting is a bit dark, though you tried using it creatively.  A reflecting board on the right would have lit up that side better.', '2006-11-19 16:29:16.000000', NULL, 1),
(3044073, 427459, 35602, '<td valign="top">Need better contrast and brightness.  The idea is a good one but compositionally it might have worked better if you had more of the gull and water, and less of the foreground.</td>', 'Need better contrast and brightness.  The idea is a good one but compositionally it might have worked better if you had more of the gull and water, and less of the foreground.', '2006-11-19 16:33:14.000000', NULL, 1),
(3044078, 425247, 35602, '<td valign="top">Great composition and nice toning.  The concentration on his face is wonderful.  I also like the repetition of design with the background and the foreground.  Well done, and you really looked at the whole image as you were shooting.</td>', 'Great composition and nice toning.  The concentration on his face is wonderful.  I also like the repetition of design with the background and the foreground.  Well done, and you really looked at the whole image as you were shooting.', '2006-11-19 16:35:01.000000', NULL, 1),
(3044084, 427390, 35602, '<td valign="top">Found the image to be too low in contrast to really love it.  Maybe a bit of fill in flash would have given more focus and detail without blown highlights.</td>', 'Found the image to be too low in contrast to really love it.  Maybe a bit of fill in flash would have given more focus and detail without blown highlights.', '2006-11-19 16:37:24.000000', NULL, 1),
(3044086, 427326, 35602, '<td valign="top">Unique take on the challenge.  Needs better focus.</td>', 'Unique take on the challenge.  Needs better focus.', '2006-11-19 16:38:55.000000', NULL, 1),
(3044087, 426156, 35602, '<td valign="top">Hmmm</td>', 'Hmmm', '2006-11-19 16:39:07.000000', NULL, 1),
