(3054099, 425693, 51538, '<td valign="top">P&amp;S cameras are perfect visual notebooks, IMO.  You were free to watch the races, worry about the tote and observe all the lovely hats.  Now try doing that with a D200 in tow... ;-)  Nice work, Enzo.</td>', 'P&S cameras are perfect visual notebooks, IMO.  You were free to watch the races, worry about the tote and observe all the lovely hats.  Now try doing that with a D200 in tow... ;-)  Nice work, Enzo.', '2006-11-22 10:51:49.000000', NULL, 0),
(3054191, 427009, 44490, '<td valign="top">You guys are so much fun!  And such great photographers - thanks for sharing your images, humor, and cheerful outlook on life.  Hope to meet you sometime, before heaven at least.</td>', 'You guys are so much fun!  And such great photographers - thanks for sharing your images, humor, and cheerful outlook on life.  Hope to meet you sometime, before heaven at least.', '2006-11-22 11:18:42.000000', NULL, 0),
